  $('#cleardiscord')?.addEventListener('click',async()=>{if(!confirm('Clear the saved Discord bot token and disconnect the bot? Channel mappings will be kept.'))return;try{await api('/api/discord/token',{method:'DELETE'});discordPendingToken='';result.textContent='Saved token cleared.';setTimeout(render,500)}catch(e){result.textContent=e.message}});
